--- src/webhooks/retry.ts
@@ -12,14 +12,22 @@ export async function deliverWebhook(event: ChargeEvent): Promise<void> {
-  await post(event.endpoint, event.payload);
+  for (let attempt = 0; attempt <= MAX_RETRIES; attempt++) {
+    try {
+      await post(event.endpoint, event.payload);
+      return;
+    } catch (err) {
+      await sleep(1000);
+    }
+  }
 }

--- src/webhooks/config.ts
@@ -3,3 +3,4 @@
 export const WEBHOOK_TIMEOUT_MS = 5000;
+export const MAX_RETRIES = 5;

--- test/webhooks/retry.test.ts
@@ -0,0 +1,11 @@
+import { deliverWebhook } from '../../src/webhooks/retry';
+
+it('retries a failed delivery', async () => {
+  post.mockRejectedValueOnce(new Error('timeout'));
+  post.mockResolvedValueOnce(undefined);
+  await deliverWebhook(event);
+  expect(post).toHaveBeenCalledTimes(2);
+});
